 $x=$report->report($B,$B);$s=$x['summary'];foreach(['gross_sales'=>100000,'discount_total'=>10000,'net_tax_amount'=>9000,'sales_without_tax'=>90000,'net_sales'=>99000] as $k=>$v)ck($s[$k]-$base[$k]===$v,'real report delta '.$k);
